using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UIElements;

// 16x16 item, gear and skill icons generated by Tools/PixelArt (`node icons.js --export`):
//   Resources/Icons/Items/<id>.png    consumables, materials, key items (and the legacy Database.Items)
//   Resources/Icons/Gear/<id>.png     every EquipmentDef in Database.Equipment and CatalogueEquipment
//   Resources/Icons/Skills/<id>.png   active skills;  Resources/Icons/Passives/<id>.png  passive skills
// Drawn at whole-number scales (3x = 48px in a 56px slot) so the pixels stay crisp.
namespace Obscure
{
    public static class IconArt
    {
        public const int Size = 16;
        static readonly Dictionary<string, Texture2D> cache = new Dictionary<string, Texture2D>();

        public static Texture2D Item(string id) => Load("Items", id);
        public static Texture2D Gear(string id) => Load("Gear", id);
        public static Texture2D Gear(EquipmentDef def) => def == null ? null : Load("Gear", def.id);
        public static Texture2D Skill(string id) => Load("Skills", id);
        public static Texture2D Passive(string id) => Load("Passives", id);
        public static Texture2D SkillOrPassive(string id, bool passive) => passive ? Passive(id) : Skill(id);

        static Texture2D Load(string folder, string id)
        {
            if (string.IsNullOrEmpty(id)) return null;
            string key = folder + "/" + id;
            if (cache.TryGetValue(key, out var t) && (t == null || t)) return t;
            t = Resources.Load<Texture2D>("Icons/" + key);
            if (t != null) t.filterMode = FilterMode.Point;
            return cache[key] = t;
        }

        // Icon centred in a slot / node, placed under the slot's own labels so badges and counts stay on top.
        public static VisualElement Overlay(VisualElement host, Texture2D tex, int scale = 3, float opacity = 1f)
        {
            if (host == null || tex == null) return null;
            int s = Size * scale;
            var el = Make(tex, s);
            el.style.position = Position.Absolute;
            el.style.left = Length.Percent(50); el.style.top = Length.Percent(50);
            el.style.marginLeft = -s / 2f; el.style.marginTop = -s / 2f;
            el.style.opacity = opacity;
            host.Insert(0, el);
            return el;
        }

        // Icon as a flex child (list rows, menus).
        public static VisualElement Inline(Texture2D tex, int scale = 3, float marginRight = 10f)
        {
            if (tex == null) return null;
            var el = Make(tex, Size * scale);
            el.style.flexShrink = 0;
            el.style.marginRight = marginRight;
            return el;
        }

        static VisualElement Make(Texture2D tex, int s)
        {
            var el = new VisualElement { pickingMode = PickingMode.Ignore, name = "icon" };
            el.style.width = s; el.style.height = s;
            el.style.backgroundImage = new StyleBackground(tex);
            return el;
        }
    }
}
